#!/usr/bin/env python3
"""Extract the visible C++20 fence and compare it with direct rectangle inspection
and independent enumeration of disjoint path subsets.
Usage: python3 checker.py [article.mdx] [--sanitize]
"""
from pathlib import Path
import os
import shutil
import re
import subprocess
import sys
import tempfile
DEFAULT = Path(__file__).resolve().parents[1] / "src/content/docs/techniques/skyline-cartesian-star-paths.mdx"
args = [arg for arg in sys.argv[1:] if arg != "--sanitize"]
article = Path(args[0]) if args else DEFAULT
blocks = re.findall(r"^```cpp\s*\n(.*?)^```\s*$", article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError("expected exactly one complete visible C++ fence")
TESTS = '#include <array>\n#include <bit>\n#include <chrono>\n#include <cstdlib>\n#include <functional>\n#include <iostream>\n#include <limits>\n#include <random>\nusing Int = std::int64_t;\nstd::uint64_t checks=0, boards=0, star_sets=0, weighted_sets=0, trees=0;\nvoid require(bool ok,const char* reason) {\n    ++checks;\n    if(!ok) {std::cerr<<"FAIL: "<<reason<<\'\\n\';std::exit(1);}\n}\n// Enumerate every axis-aligned rectangle and inspect all its pixels directly.\nstd::vector<bool> legal_retained_sets(const std::vector<int>& building,\n                                    const std::vector<std::pair<int,int>>& cells) {\n    int n=int(building.size()),q=int(cells.size());\n    std::vector<std::vector<int>> at(n,std::vector<int>(n+1,-1));\n    for(int i=0;i<q;++i) at[cells[i].first][cells[i].second]=i;\n    std::vector<unsigned> rectangles;\n    for(int x0=0;x0<n;++x0) for(int x1=x0;x1<n;++x1)\n        for(int y0=1;y0<=n;++y0) for(int y1=y0;y1<=n;++y1) {\n            bool white=false;unsigned mask=0;\n            for(int x=x0;x<=x1;++x) for(int y=y0;y<=y1;++y) {\n                if(y<=building[x]) white=true;\n                if(at[x][y]!=-1) mask|=1U<<at[x][y];\n            }\n            if(!white) rectangles.push_back(mask);\n        }\n    std::vector<bool> legal(1U<<q,true);\n    for(unsigned kept=0;kept<legal.size();++kept)\n        for(unsigned rectangle:rectangles)\n            if(std::popcount(kept&rectangle)>1) {legal[kept]=false;break;}\n    return legal;\n}\nvoid every_small_image() {\n    for(int n=1;n<=4;++n) {\n        int count=1;for(int c=0;c<n;++c) count*=n;\n        for(int code=0;code<count;++code) {\n            int value=code;std::vector<int> building(n);\n            for(int& h:building) {h=1+value%n;value/=n;}\n            std::vector<std::pair<int,int>> cells;\n            for(int x=0;x<n;++x) for(int y=building[x]+1;y<=n;++y) cells.push_back({x,y});\n            const auto legal=legal_retained_sets(building,cells);\n            int q=int(cells.size());unsigned count_sets=1U<<q;\n            std::vector<Int> sum(count_sets),best(count_sets);\n            for(unsigned mask=1;mask<count_sets;++mask) {\n                int bit=std::countr_zero(mask);\n                Int cost=1+(cells[bit].first*17+cells[bit].second*7)%13;\n                sum[mask]=sum[mask&(mask-1)]+cost;\n            }\n            for(unsigned mask=0;mask<count_sets;++mask) best[mask]=legal[mask]?sum[mask]:0;\n            for(int bit=0;bit<q;++bit) for(unsigned mask=0;mask<count_sets;++mask)\n                if(mask&(1U<<bit)) best[mask]=std::max(best[mask],best[mask^(1U<<bit)]);\n            for(unsigned mask=0;mask<count_sets;++mask) {\n                std::vector<SkylineStar> stars;\n                for(int bit=0;bit<q;++bit) if(mask&(1U<<bit)) {\n                    auto [x,y]=cells[bit];stars.push_back({x,y,1+(x*17+y*7)%13});\n                }\n                require(minimum_skyline_star_deletion(building,stars)==sum[mask]-best[mask],"all skyline/star subsets with direct rectangle oracle");\n                ++star_sets;\n            }\n            if(n<=3) {\n                int ternary=1;for(int bit=0;bit<q;++bit) ternary*=3;\n                for(int code2=0;code2<ternary;++code2) {\n                    int digits=code2;unsigned mask=0;Int total=0,kept_best=0;\n                    std::vector<SkylineStar> stars;\n                    std::vector<int> cost(q,0);\n                    for(int bit=0;bit<q;++bit) {\n                        cost[bit]=digits%3;digits/=3;\n                        if(cost[bit]) {mask|=1U<<bit;total+=cost[bit];auto [x,y]=cells[bit];stars.push_back({x,y,cost[bit]});}\n                    }\n                    for(unsigned kept=mask;;kept=(kept-1)&mask) {\n                        if(legal[kept]) {\n                            Int score=0;for(int bit=0;bit<q;++bit) if(kept&(1U<<bit)) score+=cost[bit];\n                            kept_best=std::max(kept_best,score);\n                        }\n                        if(!kept) break;\n                    }\n                    require(minimum_skyline_star_deletion(building,stars)==total-kept_best,"all absent/cost1/cost2 small images");\n                    ++weighted_sets;\n                }\n            }\n            ++boards;\n        }\n    }\n}\nInt direct_packing(const std::vector<int>& parent,const std::vector<AncestorWeightedPath>& paths) {\n    std::vector<unsigned> vertices;\n    for(const auto& path:paths) {\n        unsigned mask=0;int v=path.bottom;\n        while(true) {mask|=1U<<v;if(v==path.top) break;v=parent[v];}\n        vertices.push_back(mask);\n    }\n    Int answer=0;\n    auto search=[&](auto&& self,std::size_t at,unsigned used,Int score)->void {\n        if(at==paths.size()) {answer=std::max(answer,score);return;}\n        self(self,at+1,used,score);\n        if(!(used&vertices[at])) self(self,at+1,used|vertices[at],score+paths[at].weight);\n    };\n    search(search,0,0,0);return answer;\n}\nvoid all_small_trees() {\n    for(int n=1;n<=4;++n) {\n        std::vector<int> parent(n,-1);\n        auto visit=[&](auto&& self,int v)->void {\n            if(v<n) {for(int p=0;p<v;++p){parent[v]=p;self(self,v+1);}return;}\n            std::vector<AncestorWeightedPath> all;\n            for(int bottom=0;bottom<n;++bottom)\n                for(int top=bottom;top!=-1;top=parent[top]) all.push_back({top,bottom,1+(top*11+bottom*7)%19});\n            for(unsigned chosen=0;chosen<(1U<<all.size());++chosen) {\n                std::vector<AncestorWeightedPath> paths;\n                for(std::size_t p=0;p<all.size();++p) if(chosen&(1U<<p)) paths.push_back(all[p]);\n                require(maximum_disjoint_ancestor_path_weight(parent,paths)==direct_packing(parent,paths),"every small ancestor-path input subset");\n            }\n            ++trees;\n        };\n        visit(visit,1);\n    }\n    std::mt19937 rng(3222020);\n    for(int trial=0;trial<1800;++trial) {\n        int n=1+int(rng()%15);std::vector<int> original(n,-1),label(n),parent(n);\n        for(int v=1;v<n;++v) original[v]=int(rng()%unsigned(v));\n        for(int v=0;v<n;++v) label[v]=v;\n        std::shuffle(label.begin(),label.end(),rng);\n        for(int v=0;v<n;++v) parent[label[v]]=original[v]==-1?-1:label[original[v]];\n        std::vector<AncestorWeightedPath> paths;\n        for(int p=0;p<14;++p) {\n            int bottom=int(rng()%unsigned(n)),top=bottom;\n            while(original[top]!=-1 && rng()%2) top=original[top];\n            paths.push_back({label[top],label[bottom],Int(rng()%1000000001U)});\n        }\n        require(maximum_disjoint_ancestor_path_weight(parent,paths)==direct_packing(parent,paths),"random relabeled rooted trees / independent path set packing");\n    }\n}\nvoid official_and_boundaries() {\n    require(minimum_skyline_star_deletion({1,3,4,2,3},{{0,5,3},{3,3,2},{1,4,2}})==2,"official sample 1");\n    require(minimum_skyline_star_deletion({5,6,2,3,6,7,6},{{6,7,5},{2,3,7},{2,7,10},{0,7,6},{3,7,8}})==16,"official sample 2");\n    require(minimum_skyline_star_deletion({6,8,5,7,3,4,2,1},{{7,2,9},{5,6,7},{7,3,18},{4,8,17},{7,5,3},{4,5,3},{4,4,8},{0,8,13},{0,7,5},{6,4,13}})==44,"official sample 3");\n    require(minimum_skyline_star_deletion({1,3,1,5,1},{{0,3,9},{2,3,10}})==0,"height equal to separating building blocks rectangle");\n    require(minimum_skyline_star_deletion({1,3,1,5,1},{{0,4,9},{2,4,10}})==9,"one higher row crosses separating building");\n    require(minimum_skyline_star_deletion({1,1,1},{{0,2,9},{0,3,10}})==9,"distinct stars in one column conflict");\n    require(maximum_disjoint_ancestor_path_weight({-1,0,0,1,1,2},{{0,3,10},{1,4,8},{2,5,9}})==19,"off-path subtree contribution");\n    require(maximum_disjoint_ancestor_path_weight({-1,0},{{0,1,3},{1,1,5},{0,0,7}})==12,"top endpoint and singleton alternative");\n    require(maximum_disjoint_ancestor_path_weight({}, {})==0,"empty generic tree");\n    require(maximum_disjoint_ancestor_path_weight({-1,0},{{0,0,0},{1,1,0}})==0,"zero-weight generic paths");\n}\nvoid maximum_cases() {\n    const int n=200000;constexpr Int big=1000000000;\n    std::vector<int> building(n,1),parent(n,-1);\n    std::vector<SkylineStar> stars;\n    std::vector<AncestorWeightedPath> paths;\n    stars.reserve(n);paths.reserve(n);\n    for(int v=0;v<n;++v) {stars.push_back({v,n,big});parent[v]=v-1;paths.push_back({v,v,big});}\n    require(maximum_disjoint_ancestor_path_weight(parent,paths)==Int(n)*big,"maximum deep tree and 64bit packing sum");\n    require(minimum_skyline_star_deletion(building,stars)==Int(n-1)*big,"maximum equal heights, root-spanning stars, 64bit deletion sum");\n    for(int v=0;v<n;++v) {parent[v]=v?0:-1;paths[v]={0,v,big};}\n    require(maximum_disjoint_ancestor_path_weight(parent,paths)==big,"maximum branching tree and shared top");\n    stars.clear();\n    for(int v=0;v<n;++v) {building[v]=v+1;if(v+1<n) stars.push_back({v,v+2,big});}\n    stars.push_back({0,3,big});\n    require(minimum_skyline_star_deletion(building,stars)==big,"maximum increasing skyline / exact height boundaries");\n    std::reverse(building.begin(),building.end());for(auto& star:stars) star.column=n-1-star.column;\n    require(minimum_skyline_star_deletion(building,stars)==big,"maximum decreasing skyline and reflection");\n    stars.clear();\n    for(int v=0;v<n;++v) {\n        building[v]=v%2?n:1;\n        if(v%2==0) {stars.push_back({v,n,big});stars.push_back({v,n-1,1});}\n    }\n    require(minimum_skyline_star_deletion(building,stars)==n/2,"maximum separated columns and same-column alternatives");\n    // A balanced Cartesian tree with many path lengths; reflection preserves every rectangle.\n    struct Segment {int low,high,height;};std::vector<Segment> pending{{0,n,n}};\n    while(!pending.empty()) {\n        auto [low,high,height]=pending.back();pending.pop_back();if(low==high) continue;\n        int mid=(low+high)/2;building[mid]=height;\n        pending.push_back({low,mid,height-1});pending.push_back({mid+1,high,height-1});\n    }\n    stars.clear();std::mt19937 rng(20200322);\n    for(int v=0;v<n;++v) if(building[v]<n) {\n        int y=building[v]+1+int(rng()%unsigned(n-building[v]));\n        stars.push_back({v,y,1+Int(rng()%1000000000U)});\n    }\n    const auto first_star=stars.front();\n    int second_height=first_star.height==n?n-1:n;\n    stars.push_back({first_star.column,second_height,1000000000});\n    require(int(stars.size())==n,"balanced stress has maximum M");\n    Int value=minimum_skyline_star_deletion(building,stars);\n    std::reverse(building.begin(),building.end());for(auto& star:stars) star.column=n-1-star.column;\n    require(minimum_skyline_star_deletion(building,stars)==value,"maximum balanced skyline reflection invariant");\n}\ntemplate<class F> void invalid(F action) {\n    bool caught=false;try{action();}catch(const std::invalid_argument&){caught=true;}\n    require(caught,"invalid argument was accepted");\n}\nvoid invalid_cases() {\n    invalid([]{minimum_skyline_star_deletion({},{});});\n    invalid([]{minimum_skyline_star_deletion({0},{});});\n    invalid([]{minimum_skyline_star_deletion({2},{});});\n    invalid([]{minimum_skyline_star_deletion(std::vector<int>(200001,1),{});});\n    invalid([]{minimum_skyline_star_deletion({1,1},std::vector<SkylineStar>(200001,{0,2,1}));});\n    for(const auto& star:std::vector<SkylineStar>{{-1,2,1},{2,2,1},{0,0,1},{0,1,1},{0,3,1},{0,2,0},{0,2,-1},{0,2,1000000001},\n        {std::numeric_limits<int>::min(),2,1},{std::numeric_limits<int>::max(),2,1},\n        {0,2,std::numeric_limits<Int>::min()},{0,2,std::numeric_limits<Int>::max()}})\n        invalid([&]{minimum_skyline_star_deletion({1,1},{star});});\n    invalid([]{minimum_skyline_star_deletion({1,1},{{0,2,1},{0,2,7}});});\n    for(const auto& parent:std::vector<std::vector<int>>{{-1,-1},{1,0},{-1,2,1},{-2},{0},{-1,2}})\n        invalid([&]{maximum_disjoint_ancestor_path_weight(parent,{});});\n    invalid([]{maximum_disjoint_ancestor_path_weight({},{{0,0,1}});});\n    invalid([]{maximum_disjoint_ancestor_path_weight(std::vector<int>(200001,-1),{});});\n    invalid([]{maximum_disjoint_ancestor_path_weight({-1},std::vector<AncestorWeightedPath>(200001,{0,0,1}));});\n    for(const auto& path:std::vector<AncestorWeightedPath>{{-1,0,1},{0,3,1},{1,2,1},{0,1,-1},{0,1,1000000001},\n        {0,1,std::numeric_limits<Int>::min()},{0,1,std::numeric_limits<Int>::max()}})\n        invalid([&]{maximum_disjoint_ancestor_path_weight({-1,0,0},{path});});\n}\nint main() {\n    auto started=std::chrono::steady_clock::now();\n    every_small_image();all_small_trees();official_and_boundaries();maximum_cases();invalid_cases();\n    std::cout<<"checks="<<checks<<" exhaustive_boards="<<boards<<" all_star_subsets="<<star_sets\n             <<" all_weighted_small_images="<<weighted_sets<<" exhaustive_trees="<<trees\n             <<" total_seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count()<<\'\\n\';\n}\n'
with tempfile.TemporaryDirectory(prefix="flowchartcp-constellation-") as directory:
    source = Path(directory) / "check.cpp"
    binary = Path(directory) / "check"
    source.write_text(blocks[0] + "\n" + TESTS)
    flags = ["-std=c++20", "-O2", "-Wall", "-Wextra", "-Werror"]
    environment = os.environ.copy()
    if "--sanitize" in sys.argv:
        flags += ["-g", "-fsanitize=address,undefined", "-fno-omit-frame-pointer"]
        environment["ASAN_OPTIONS"] = "detect_leaks=0"
    compiler = os.environ.get("CXX") or shutil.which("g++") or shutil.which("clang++") or "c++"
    subprocess.run([compiler, *flags, str(source), "-o", str(binary)], check=True, timeout=120)
    subprocess.run([str(binary)], check=True, env=environment, timeout=180)
